INSERT INTO collection_pages VALUES('88859ebedafd5c2fc9a97d17152c7b9c085f38c3fe2a596f24922e6662b35bea','62ed2a6bbb6401d096aad7a3a116fa64f989d5ff2c012ff0ce6f02a3324308ab','{"hasNext":false,"items":[{"author":{"account":{"login":"MohitGhodke","providerType":"User"},"email":"33804608+MohitGhodke@users.noreply.github.com","name":"MohitGhodke"},"authoredDate":"2026-08-13T01:07:27Z","committedDate":"2026-08-13T01:07:27Z","committer":{"account":{"login":"MohitGhodke","providerType":"User"},"email":"33804608+MohitGhodke@users.noreply.github.com","name":"MohitGhodke"},"observedAt":"2026-10-09T00:11:27.277Z","repositoryId":1332570775,"sha":"7d1c07cf62e80c7711aa83e96980eccf2ec4cd83"}],"observedAt":"2026-10-09T00:11:27.277Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/33804608?v=4","events_url":"https://api.github.com/users/MohitGhodke/events{/privacy}","followers_url":"https://api.github.com/users/MohitGhodke/followers","following_url":"https://api.github.com/users/MohitGhodke/following{/other_user}","gists_url":"https://api.github.com/users/MohitGhodke/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/MohitGhodke","id":33804608,"login":"MohitGhodke","node_id":"MDQ6VXNlcjMzODA0NjA4","organizations_url":"https://api.github.com/users/MohitGhodke/orgs","received_events_url":"https://api.github.com/users/MohitGhodke/received_events","repos_url":"https://api.github.com/users/MohitGhodke/repos","site_admin":false,"starred_url":"https://api.github.com/users/MohitGhodke/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/MohitGhodke/subscriptions","type":"User","url":"https://api.github.com/users/MohitGhodke","user_view_type":"public"},"comments_url":"https://api.github.com/repos/MohitGhodke/MicroFrontendSample/commits/7d1c07cf62e80c7711aa83e96980eccf2ec4cd83/comments","commit":{"author":{"date":"2026-08-13T01:07:27Z","email":"33804608+MohitGhodke@users.noreply.github.com","name":"MohitGhodke"},"comment_count":0,"committer":{"date":"2026-08-13T01:07:27Z","email":"33804608+MohitGhodke@users.noreply.github.com","name":"MohitGhodke"},"message":"Add Angular micro frontend sample with three applications\n\nA minimal, runnable demonstration of runtime composition with Native\nFederation: one product list owned by products-mfe and loaded at runtime\ninto two independent host applications.\n\n- products-mfe (:4201) exposes ProductList and owns its own data\n- store-shell (:4200) and admin-shell (:4202) mount it at runtime\n- Angular shared as a singleton so it downloads once, not twice\n- Each mount point has an error boundary, so a failed remote degrades\n  to one unavailable panel rather than a broken page\n\nDocumentation is a first-class part of the sample: 17 [Cn] markers in the\nsource are each explained in EXPLANATION.md, which is written for readers\nnew to micro frontends.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"b693bca87d3301071df9f1a1677da9e6f574c4ec","url":"https://api.github.com/repos/MohitGhodke/MicroFrontendSample/git/trees/b693bca87d3301071df9f1a1677da9e6f574c4ec"},"url":"https://api.github.com/repos/MohitGhodke/MicroFrontendSample/git/commits/7d1c07cf62e80c7711aa83e96980eccf2ec4cd83","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/33804608?v=4","events_url":"https://api.github.com/users/MohitGhodke/events{/privacy}","followers_url":"https://api.github.com/users/MohitGhodke/followers","following_url":"https://api.github.com/users/MohitGhodke/following{/other_user}","gists_url":"https://api.github.com/users/MohitGhodke/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/MohitGhodke","id":33804608,"login":"MohitGhodke","node_id":"MDQ6VXNlcjMzODA0NjA4","organizations_url":"https://api.github.com/users/MohitGhodke/orgs","received_events_url":"https://api.github.com/users/MohitGhodke/received_events","repos_url