INSERT INTO collection_pages VALUES('3ee62aebf97c99548072824e209b395c3b08894d0de486626ad135589b8f9ceb','cbcee1ca4d433b0cacd3173c028f0a72bba3cc16fdcd110fab0aa0093f4940bd','{"hasNext":false,"items":[{"author":{"account":{"login":"moody608","providerType":"User"},"email":"moody608@outlook.com","name":"moody608"},"authoredDate":"2026-08-14T19:35:05Z","committedDate":"2026-08-14T19:35:05Z","committer":{"account":{"login":"moody608","providerType":"User"},"email":"moody608@outlook.com","name":"moody608"},"observedAt":"2026-10-09T00:12:01.267Z","repositoryId":1333413964,"sha":"88024ef7e902af0bd953794f2f2e2d454efc42c2"},{"author":{"account":{"login":"moody608","providerType":"User"},"email":"moody608@outlook.com","name":"moody608"},"authoredDate":"2026-08-14T15:25:55Z","committedDate":"2026-08-14T15:25:55Z","committer":{"account":{"login":"moody608","providerType":"User"},"email":"moody608@outlook.com","name":"moody608"},"observedAt":"2026-10-09T00:12:01.267Z","repositoryId":1333413964,"sha":"a770eb0a71ab8db66c7509c38258f5ffffa0baf4"},{"author":{"account":{"login":"moody608","providerType":"User"},"email":"moody608@outlook.com","name":"moody608"},"authoredDate":"2026-08-13T18:17:10Z","committedDate":"2026-08-13T18:17:10Z","committer":{"account":{"login":"moody608","providerType":"User"},"email":"moody608@outlook.com","name":"moody608"},"observedAt":"2026-10-09T00:12:01.267Z","repositoryId":1333413964,"sha":"81688156628a8359b29ce72ac23d046a8ce8129c"}],"observedAt":"2026-10-09T00:12:01.267Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/28807229?v=4","events_url":"https://api.github.com/users/moody608/events{/privacy}","followers_url":"https://api.github.com/users/moody608/followers","following_url":"https://api.github.com/users/moody608/following{/other_user}","gists_url":"https://api.github.com/users/moody608/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/moody608","id":28807229,"login":"moody608","node_id":"MDQ6VXNlcjI4ODA3MjI5","organizations_url":"https://api.github.com/users/moody608/orgs","received_events_url":"https://api.github.com/users/moody608/received_events","repos_url":"https://api.github.com/users/moody608/repos","site_admin":false,"starred_url":"https://api.github.com/users/moody608/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/moody608/subscriptions","type":"User","url":"https://api.github.com/users/moody608","user_view_type":"public"},"comments_url":"https://api.github.com/repos/jmoo900/c8y-ai-chat-wrapper/commits/88024ef7e902af0bd953794f2f2e2d454efc42c2/comments","commit":{"author":{"date":"2026-08-14T19:35:05Z","email":"moody608@outlook.com","name":"moody608"},"comment_count":0,"committer":{"date":"2026-08-14T19:35:05Z","email":"moody608@outlook.com","name":"moody608"},"message":"Add clear-conversation control and error hint, fix federation config\n\n- Clear-conversation trash icon, projected into the dashboard''s shared\n  widget title bar via <c8y-widget-action>, with a fallback for contexts\n  with no DashboardChildComponent ancestor (e.g. the config preview).\n  Also explicitly clears a settled agentRequestError, since\n  resetMessages() alone only ever sets that signal, never clears it.\n- Supplementary error hint below the chat, explaining likely causes\n  (long conversation vs AI Agent Manager issue) since AgentChatComponent''s\n  own banner is often a generic fallback message. Suppressed for the\n  \"AI response cancelled.\" case so cancelling doesn''t look like a failure.\n  Background color matched to the composer bar''s actual computed value.\n- Debug-only \"Simulate error\" control to preview the hint without\n  spending real tokens on a genuinely long conversation.\n- Added @ngx-translate/core to the Module Federation shared package list\n  (cumulocity.config.ts) and pinned it as an explicit dependency at the\n  version @c8y/ngx-components itself depends on - it was being bundled\n  as a private copy, causing inject(TranslateService) to fail with\n  NG0201 against the shell''s actual shared instance.\n- Trimmed the Meridian Ops Insights Agent prompt to cut per-turn token\n  overhead (merged device/equipment-type resolution, narrower default\n  tool-call parameters).\n- Bumped plugin version to 1.0.1 so deploying overwrites the prior\n  install rather than needing a separate uninstall step.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"4e4ef4d12c6d7d1037234f4584a6eded7dc3ab15","url":"https://api.github.com/repos/jmoo900/c8y-ai-chat-wrapper/git/trees/4e4ef4d12c6d7d1037234f4584a6eded7dc3ab15"},"url":"https://api.github.com/repos/jmoo900/c8y-ai-chat-wrapper/git/commits/88024ef7e902af0bd953794f2f2e2d454efc42c2","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/28807229?v=4","events_url":"https://api.github.com/users/moody608/events{/privacy}","followers_url":"https://api.github.com/users/moody608/followers","following_url":"https://api.github.com/users/moody608/following{/other_user}","gists_url":"https://api.github.com/users/moody608/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/moody608","id":28807229,"login":"moody608","node_id":"MDQ6VXNlcjI4ODA3MjI5","organizations_url":"https://api.github.com/users/moody608/orgs","received_events_url":"https://api.github.com/users/moody608/received_events","repos_url":"https://api.github.com/users/moody608/repos","site_admin":false,"starred_url":"https://api.github.com/users/moody608/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/moody608/subscriptions","type":"User","url":"https://api.github.com/users/moody608","user_view_type":"public"},"html_url":"https://github.com/jmoo900/c8y-ai-chat-wrapper/commit/88024ef7e902af0bd953794f2f2e2d454efc42c2","node_id":"C_kwDOT3pITNoAKDg4MDI0ZWY3ZTkwMmFmMGJkOTUzNzk0ZjJmMmUyZDQ1NGVmYzQyYzI","parents":[{"html_url":"https://github.com/jmoo900/c8y-ai-chat-wrapper/commit/a770eb0a71ab8db66c7509c38258f5ffffa0baf4","sha":"a770eb0a71ab8db66c7509c38258f5ffffa0baf4","url":"https://api.github.com/repos/jmoo900/c8y-ai-chat-wrapper/commits/a770eb0a71ab8db66c7509c38258f5ffffa0baf4"}],"sha":"88024ef7e902af0bd953794f2f2e2d454efc42c2","url":"https://api.github.com/repos/jmoo900/c8y-ai-chat-wrapper/commits/88024ef7e902af0bd953794f2f2e2d454efc42c2"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/28807229?v=4","events_url":"https://api.github.com/users/moody608/events{/privacy}","followers_url":"https://api.github.com/users/moody608/followers","following_url":"https://api.github.com/users/moody608/following{/other_user}","gists_url":"https://api.github.com/users/moody608/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/moody608","id":28807229,"login":"moody608","node_id":"MDQ6VXNlcjI4ODA3MjI5","organizations_url":"https://api.github.com/users/moody608/orgs","received_events_url":"https://api.github.com/users/moody608/received_events","repos_url":"https://api.github.com/users/moody608/repos","site_admin":false,"starred_url":"https://api.github.com/users/moody608/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/moody608/subscriptions","type":"User","url":"https://api.github.com/users/moody608","user_view_type":"public"},"comments_url":"https://api.github.com/repos/jmoo900/c8y-ai-chat-wrapper/commits/a770eb0a71ab8db66c7509c38258f5ffffa0baf4/comments","commit":{"author":{"date":"2026-08-14T15:25:55Z","email":"moody608@outlook.com","name":"moody608"},"comment_count":0,"committer":{"date":"2026-08-14T15:25:55Z","email":"moody608@outlook.com","name":"moody608"},"message":"Add AI context chat widget plugin\n\nCockpit dashboard widget wrapping the platform''s own AgentChatComponent,\nscoped to whatever device/asset/group the dashboard is currently viewing.\nIncludes a config page matching the stock AI Agent Chat widget, a Vitest\nsuite, and supporting docs.\n\nCo